"""Compile the shipped startup FIR literals into immutable fixed-V10 profiles.

This does not fit, quantize, or reformat a coefficient. Every C float token is
copied from model.c, so the generated constants have identical FP32 values.
"""
from pathlib import Path
import argparse
import re


def compile_profiles(source: Path) -> str:
    text = source.read_text(encoding="utf-8")
    lines = [
        "/* Generated by tools/compile_fixed_startup.py from the six model.c FIRs.",
        "   Original float tokens retained. No PCM or initialization workspace. */",
        "static const SfProfile sfl_fixed_profiles[3]={",
    ]
    for stage in range(3):
        lines.append("{.rate=48000,.count=2,.warmup_frames=48000,.band={")
        for channel in range(2):
            pattern = rf"static const float taps_{stage}_{channel}\[512\]=\{{(.*?)\}};"
            match = re.search(pattern, text, re.S)
            if match is None:
                raise ValueError(f"missing FIR {stage}/{channel}")
            tokens = [token.strip() for token in match.group(1).split(",") if token.strip()]
            if len(tokens) != 512 or any(not token.endswith("f") for token in tokens):
                raise ValueError(f"invalid FIR {stage}/{channel}")
            lines.append("{.count=512,.gain=0.70710678118654746f,.right_over_left=" +
                         ("1" if channel == 0 else "-1") + ",.taps={")
            for begin in range(0, 512, 6):
                lines.append("    " + ",".join(tokens[begin:begin + 6]) + ",")
            lines.append("},.decimation=0},")
        lines.append("}},")
    lines.append("};")
    return "\n".join(lines) + "\n"


if __name__ == "__main__":
    root = Path(__file__).resolve().parents[1]
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, default=root / "modules/startup_flare/model.c")
    parser.add_argument("--output", type=Path, default=root / "modules/startup_flare/fixed_profiles.inc")
    args = parser.parse_args()
    args.output.write_text(compile_profiles(args.source), encoding="utf-8", newline="\n")
